insert into public.mystery_cases (id, title, intro, ending) values ('lighthouse-letter', 'The Lighthouse Letter', 'It is Mira and Tom''s tenth anniversary at the Harbour Hotel. At 8:30 pm Mira left a sealed letter for Tom at reception. By 9:40 it was gone. Work out what happened - but each of you only holds half the evidence.', 'At midnight Tom climbed the lighthouse and found Mira''s letter waiting in the lantern room, lit by the sweep of the beam. Nadia, Mira''s oldest friend, had borrowed it during the alarm test so it could be read somewhere unforgettable. The note she added said only: ''Some letters deserve a view.''');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('lighthouse-letter', 1, 'The missing minutes', 'The letter sat in pigeonhole 12 behind the reception desk. Somewhere between 8:30 and 9:40 it disappeared.', 'When was the letter most likely taken?', '[{"id": "t1", "label": "Around 8:15 pm"}, {"id": "t2", "label": "Around 8:45 pm"}, {"id": "t3", "label": "Around 9:20 pm"}, {"id": "t4", "label": "Around 9:50 pm"}]'::jsonb, 't3', 'The desk was only unattended during the fire-alarm test, 9:15 to 9:25. The letter was taken in that window.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 1, 1, 1, 'Reception log', 'Letter for Room 9 placed in pigeonhole 12 at 8:30 pm. Desk staffed all evening except during the alarm test.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 1, 1, 2, 'Guest comment', 'A guest complained the receptionist ''vanished for a few minutes when the alarms went off''.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 1, 2, 1, 'Maintenance note', 'Scheduled fire-alarm test: started 9:15 pm, all clear at 9:25 pm.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 1, 2, 2, 'Night porter''s round', 'Checked pigeonholes at 9:40 pm. Number 12 empty.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 1, 1, 'When could someone reach the pigeonholes without being seen?');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 1, 2, 'Line up the alarm test times with the porter''s round.');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('lighthouse-letter', 2, 'Who was free?', 'Four people were near reception that evening: Ben the night porter, Leo the chef, Tom himself, and Nadia, a guest in Room 4.', 'Who took the letter?', '[{"id": "ben", "label": "Ben, the night porter"}, {"id": "leo", "label": "Leo, the chef"}, {"id": "tom", "label": "Tom"}, {"id": "nadia", "label": "Nadia, the guest in Room 4"}]'::jsonb, 'nadia', 'Leo, Ben and Tom all have firm alibis for 9:15 to 9:25. Only Nadia was unaccounted for - and the red thread matches her scarf.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 2, 1, 1, 'Car park head count', 'During the alarm test all kitchen staff gathered in the car park. Head count signed by Leo at 9:17 and 9:24.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 2, 1, 2, 'Desk hinge', 'A strand of red wool was caught on the reception desk hinge.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 2, 2, 1, 'Roof access log', 'Ben escorted the maintenance engineer on the roof from 9:10 to 9:30.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 2, 2, 2, 'Bar receipts', 'Tom paid at the rooftop bar at 9:16 and 9:24. The barman says he never left his stool.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 2, 2, 3, 'Lost property', 'Nadia asked the morning staff if anyone had found ''a few threads from my red scarf''.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 2, 1, 'Rule people out first: who can prove where they were from 9:15 to 9:25?');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 2, 2, 'Who is left once the alibis are checked, and does anything physical point to them?');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('lighthouse-letter', 3, 'Where is it now?', 'Nadia isn''t hiding anything - she just smiles and says the letter is ''somewhere with a better view''.', 'Where is the letter now?', '[{"id": "safe", "label": "In Nadia''s room safe"}, {"id": "lantern", "label": "In the lighthouse lantern room"}, {"id": "post", "label": "In the hotel post box"}, {"id": "fire", "label": "Burned in the lounge fireplace"}]'::jsonb, 'lantern', 'The post had already gone and the fire was never lit. The keeper took a sealed envelope from a woman in a red scarf, for the lantern room - where Tom''s midnight tour ends.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 3, 1, 1, 'Tour booking', 'Nadia booked a private lighthouse tour for 11:45 pm under the names ''Tom & Mira''.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 3, 1, 2, 'Post collection', 'The hotel post box was emptied at 9:00 pm, before the letter went missing. No later collection.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 3, 2, 1, 'Keeper''s notebook', '9:45 pm - woman in a red scarf left a sealed envelope. ''Lantern room, please, before midnight.''');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('lighthouse-letter', 3, 2, 2, 'Lounge', 'The lounge fireplace was not lit that night: chimney sweep booked for the morning.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 3, 1, 'Eliminate the places the letter couldn''t be.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('lighthouse-letter', 3, 2, 'What did the lighthouse keeper receive, and from whom?');
insert into public.mystery_cases (id, title, intro, ending) values ('orchard-photograph', 'The Orchard Photograph', 'At the Ashby Orchard summer fair, the favourite to win the photography prize - a print called ''First Light'' - vanished from the barn gallery before judging at 4 pm. Split the evidence, compare notes, and find it before the prizes are announced.', 'At 4:15 Elsie''s parents arrived for the fair and found ''First Light'' propped on their picnic table - a sunrise portrait of the two of them, taken on their first holiday together, forty years ago to the day. Elsie had withdrawn it from the competition that morning. Some prizes aren''t meant to be judged.');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('orchard-photograph', 1, 'The way in', 'The barn has four ways in: the north door, the south door, a side window and a hatch to the hay loft.', 'How did the photograph leave the barn?', '[{"id": "north", "label": "Through the north door"}, {"id": "south", "label": "Through the south door"}, {"id": "window", "label": "Through the side window"}, {"id": "loft", "label": "Through the loft hatch"}]'::jsonb, 'loft', 'The north door was locked, the window painted shut and the south door''s bell never rang. Only the loft hatch remains, and the sawdust trail confirms it.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 1, 1, 1, 'Padlock', 'The north door was padlocked all afternoon. The only key stayed with the judge.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 1, 1, 2, 'Sawdust', 'Fresh sawdust from the loft was scattered just below the hatch, then tracked across the gallery floor.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 1, 2, 1, 'Fresh paint', 'The side window was repainted yesterday. The paint seal along its edge is unbroken.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 1, 2, 2, 'The bell', 'The south door rings a bell when opened. Priya ran the honey stall beside it all day and heard nothing after lunch.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 1, 1, 'Cross off every entrance that someone can prove was unused.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 1, 2, 'Which entrance has physical evidence of use?');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('orchard-photograph', 2, 'Up the ladder', 'The loft can only be reached by a ladder on the orchard side. Four people were near the barn: Owen the caretaker, Elsie the photographer, Mr Hale the judge, and Sam, aged nine.', 'Who went through the loft?', '[{"id": "owen", "label": "Owen, the caretaker"}, {"id": "elsie", "label": "Elsie, the photographer"}, {"id": "hale", "label": "Mr Hale, the judge"}, {"id": "sam", "label": "Sam"}]'::jsonb, 'elsie', 'The ladder was only back at the barn from 3:30. Hale, Owen and Sam were elsewhere until 4. Elsie admits she was in the loft at 3:40.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 2, 1, 1, 'Borrowed ladder', 'The loft ladder was lent to the cider stall at 2 pm and only returned at 3:30 pm.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 2, 1, 2, 'Judging stage', 'Mr Hale judged pies on the main stage from 2 to 4 pm. The whole thing was filmed.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 2, 1, 3, 'Face painting', 'Sam sat with his parents in the face-painting queue from 3 pm until judging.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 2, 2, 1, 'Tractor log', 'Owen drove the tractor rides from 1 pm to 5 pm without a break.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 2, 2, 2, 'Sawdust shoes', 'Elsie''s shoes were dusted with sawdust. She said she climbed up ''about 3:40, to fix the lighting''.');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 2, 1, 'When could anyone actually use the ladder?');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 2, 2, 'Who has no alibi in that window - and who admits being up there?');
insert into public.mystery_chapters (case_id, chapter_no, title, scene, question, options, answer_id, resolution) values ('orchard-photograph', 3, 'First light', 'Elsie doesn''t deny it. ''It wasn''t stolen,'' she says. ''It was always going somewhere else.''', 'Why did Elsie take her own photograph?', '[{"id": "judging", "label": "To stop it being judged unfairly"}, {"id": "frame", "label": "To repair a damaged frame"}, {"id": "gift", "label": "To give it to someone"}, {"id": "swap", "label": "To swap in a better print"}]'::jsonb, 'gift', 'She had already withdrawn it by email at noon. The photo shows her parents at sunrise, and the gift tag in her bag explains the rest.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 3, 1, 1, 'Organiser''s inbox', 'Unread email from Elsie at 12:02 pm: ''Please withdraw First Light. It''s spoken for.''');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 3, 1, 2, 'The picture', '''First Light'' shows a couple at sunrise on a beach. Elsie''s mother is in the photograph.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 3, 2, 1, 'Car park', 'Elsie''s parents'' car arrived at 4:10 pm. Today is their 40th wedding anniversary.');
insert into public.mystery_clues (case_id, chapter_no, player_number, clue_no, title, body) values ('orchard-photograph', 3, 2, 2, 'Gift tag', 'A tag in Elsie''s bag reads: ''For forty years of first light. Love, E.''');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 3, 1, 'Did she still want the photograph in the competition?');
insert into public.mystery_hints (case_id, chapter_no, hint_no, body) values ('orchard-photograph', 3, 2, 'Who is in the photo, and why is today special for them?');
